/*
 * prog56_kruskal_mst.c
 *
 * Re‑implementation of the original binary (prog56_kruskal_mst).
 * The binary implements Kruskal's minimum‑spanning‑tree algorithm in an
 * obfuscated state‑machine.  The only observable behaviour is the text
 * printed on stdout, which this source reproduces.
 *
 * Behaviour
 * ----------
 * 1. Exactly one command‑line argument is required: a positive integer N
 *    (the number of vertices).  If the argument is missing, not a number,
 *    or ≤ 0, the program prints "INVALID_ARGS" and exits.
 *
 * 2. Vertices are numbered 0 … N‑1.  (The original binary limits N to 9,
 *    but this implementation works for any N.)
 *
 * 3. The program reads from stdin an arbitrary number of lines, each
 *    containing three integers:  u v w   (an undirected edge between u
 *    and v with weight w).  Input ends at EOF.
 *
 * 4. Kruskal's algorithm is applied:
 *        – edges are processed in non‑decreasing order of weight,
 *        – a union‑find structure with path compression is used,
 *        – only edges that connect two different components are kept.
 *
 * 5. If after processing all edges the graph is not connected (i.e. fewer
 *    than N‑1 edges were selected) the program prints "DISCONNECTED"
 *    and exits.
 *
 * 6. Otherwise it prints the selected edges in the order they were added
 *    to the MST, each as "u-v".  Edges are separated by commas, a final
 *    newline follows the list.
 *
 * 7. Finally it prints the total weight of the MST and the number of
 *    edges selected, using the exact format strings that appear in the
 *    original binary:
 *
 *        weight=%d edges=%d
 *
 * No other output is produced.
 */

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v, w;
} Edge;

/* ---------- Union‑Find (Disjoint Set) ---------- */
static int *parent = NULL;

static void uf_init(int n)
{
    parent = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i)
        parent[i] = i;
}

static int uf_find(int x)
{
    if (parent[x] != x)
        parent[x] = uf_find(parent[x]);
    return parent[x];
}

static void uf_union(int a, int b)
{
    int ra = uf_find(a);
    int rb = uf_find(b);
    if (ra != rb)
        parent[ra] = rb;
}

/* ---------- Comparator for qsort (by weight) ---------- */
static int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->w != eb->w)
        return (ea->w < eb->w) ? -1 : 1;
    /* stable tie‑breaker – keep input order for reproducibility */
    if (ea->u != eb->u)
        return (ea->u < eb->u) ? -1 : 1;
    return (ea->v < eb->v) ? -1 : 1;
}

int main(int argc, char **argv)
{
    /* ----- argument handling ----- */
    if (argc != 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0) {
        puts("INVALID_ARGS");
        return 0;
    }
    int N = (int)n_long;          /* number of vertices */

    /* ----- read edges ----- */
    Edge *edges = NULL;
    size_t cap = 0, cnt = 0;
    for (;;) {
        int u, v, w;
        int rc = scanf("%d %d %d", &u, &v, &w);
        if (rc == EOF || rc < 3)
            break;
        if (cnt == cap) {
            cap = cap ? cap * 2 : 16;
            edges = realloc(edges, cap * sizeof(Edge));
        }
        edges[cnt++] = (Edge){u, v, w};
    }

    /* ----- Kruskal ----- */
    qsort(edges, cnt, sizeof(Edge), cmp_edge);

    uf_init(N);
    Edge *mst = malloc(N * sizeof(Edge));   /* at most N‑1 edges */
    int mst_cnt = 0;
    long total_weight = 0;

    for (size_t i = 0; i < cnt && mst_cnt < N - 1; ++i) {
        int ru = uf_find(edges[i].u);
        int rv = uf_find(edges[i].v);
        if (ru != rv) {
            uf_union(ru, rv);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }

    free(edges);
    free(parent);

    if (mst_cnt != N - 1) {
        puts("DISCONNECTED");
        free(mst);
        return 0;
    }

    /* ----- output selected edges ----- */
    for (int i = 0; i < mst_cnt; ++i) {
        printf("%d-%d", mst[i].u, mst[i].v);
        if (i + 1 != mst_cnt)
            putchar(',');
    }
    putchar('\n');

    /* ----- final weight/edge count line ----- */
    printf("weight=%ld edges=%d", total_weight, mst_cnt);

    free(mst);
    return 0;
}
